324	func TestAlertsUseConsistentSnapshot(t *testing.T) {
325		h := Handler()
326		putRule(t, h, "r1", `{"kind":"threshold","operator":"gte","threshold":1,"metric":"c","labels":{}}`)
327	
328		const writers = 16
329		const iterations = 200
330		var wg sync.WaitGroup
331		for i := 0; i < writers; i++ {
332			wg.Add(1)
333			go func() {
334				defer wg.Done()
335				for j := 0; j < iterations; j++ {
336					rec := httptest.NewRecorder()
337					req := httptest.NewRequest(http.MethodPost, metricsPath, strings.NewReader(
338						`{"samples":[{"name":"c","type":"counter","labels":{},"value":1}]}`))
339					req.Header.Set("Content-Type", "application/json")
340					h.ServeHTTP(rec, req)
341					if rec.Code != http.StatusAccepted {
342						t.Errorf("post = %d", rec.Code)
343						return
344					}
345				}
346			}()
347		}
348		// Concurrent readers: every response must be valid JSON with a value that
349		// reflects some committed snapshot (0..writers*iterations), and no_data
350		// must never appear once... it may before the first commit, so only assert
351		// structural validity here.
352		for i := 0; i < 8; i++ {
353			wg.Add(1)
354			go func() {
355				defer wg.Done()
356				for j := 0; j < 100; j++ {
357					rec := getAlerts(t, h)
358					if rec.Code != http.StatusOK {
359						t.Errorf("alerts = %d", rec.Code)
360						return
361					}
362					var payload struct {
363						Alerts []struct {
364							ID    string   `json:"id"`
365							State string   `json:"state"`
366							Value *float64 `json:"value"`
367						} `json:"alerts"`
368					}
369					if err := json.Unmarshal(rec.Body.Bytes(), &payload); err != nil || len(payload.Alerts) != 1 {
370						t.Errorf("bad alerts payload: %s", rec.Body.String())
371						return
372					}
373					a := payload.Alerts[0]
374					switch a.State {
375					case "firing", "inactive":
376						if a.Value == nil {
377							t.Errorf("state %s with null value", a.State)
378						}
379					case "no_data":
380						if a.Value != nil {
381							t.Errorf("no_data with non-null value")
382						}
383					default:
384						t.Errorf("unknown state %q", a.State)
385					}
386				}
387			}()
388		}
389		wg.Wait()
390	
391		// Final value must be exactly writers*iterations — no lost updates.
392		alerts := alertsByID(t, getAlerts(t, h))
393		a := alerts["r1"].(map[string]any)
394		if a["state"] != "firing" || a["value"] != float64(writers*iterations) {
395			t.Fatalf("final alert = %v", a)
396		}
397	}
398	
399	func alertsByID(t *testing.T, rec *httptest.ResponseRecorder) map[string]any {
400		t.Helper()
401		list := decodeBody(t, rec)["alerts"].([]any)
402		out := make(map[string]any, len(list))
403		for _, item := range list {
404			m := item.(map[string]any)
405			out[m["id"].(string)] = m
406		}
407		return out
408	}
409	
410	func alertIDs(t *testing.T, rec *httptest.ResponseRecorder) []string {
411		t.Helper()
412		list := decodeBody(t, rec)["alerts"].([]any)
413		ids := make([]string, len(list))
414		for i, item := range list {
415			ids[i] = item.(map[string]any)["id"].(string)
416		}
417		return ids
418	}
