// evalAlerts computes every rule against a single consistent snapshot of
// metrics and rules; results are sorted by rule id.
func (s *metricStore) evalAlerts() []alertOutput {
	s.mu.RLock()
	defer s.mu.RUnlock()

	rules := make([]*alertRule, 0, len(s.rules))
	for _, r := range s.rules {
		rules = append(rules, r)
	}
	sort.Slice(rules, func(i, j int) bool { return rules[i].id < rules[j].id })

	out := make([]alertOutput, 0, len(rules))
	for _, r := range rules {
		al := alertOutput{ID: r.id, State: "inactive"}

		var value float64
		if r.kind == "threshold" {
			sum, ok := s.selectorSum(r.left)
			if !ok {
				al.State = "no_data"
				out = append(out, al)
				continue
			}
			value = sum
		} else {
			num, numOK := s.selectorSum(r.left)
			den, denOK := s.selectorSum(r.right)
			if !numOK || !denOK || den == 0 {
				al.State = "no_data"
				out = append(out, al)
				continue
			}
			value = num / den
		}

		v := value
		al.Value = &v
		if compareHolds(r.operator, value, r.threshold) {
			al.State = "firing"
		}
		out = append(out, al)
	}
	return out
}

