package server

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"
)

func silenceReq(t *testing.T, h http.Handler, method, id, body, ct string) *httptest.ResponseRecorder {
	t.Helper()
	target := silencesPath
	if id != "" {
		target = silencesPrefix + id
	}
	rec := httptest.NewRecorder()
	req := httptest.NewRequest(method, target, strings.NewReader(body))
	if ct != "" {
		req.Header.Set("Content-Type", ct)
	}
	h.ServeHTTP(rec, req)
	return rec
}

func putSilence(t *testing.T, h http.Handler, id, body string) *httptest.ResponseRecorder {
	t.Helper()
	return silenceReq(t, h, http.MethodPut, id, body, "application/json")
}

func rfc3339(t time.Time) string { return t.Format(time.RFC3339) }

func TestSilenceLifecycleAndStates(t *testing.T) {
	h := Handler()
	now := time.Now()

	// Rule need not exist.
	body := fmt.Sprintf(`{"rule_ids":["future_rule"],"starts_at":%q,"ends_at":%q,"comment":"maint"}`,
		rfc3339(now.Add(time.Hour)), rfc3339(now.Add(2*time.Hour)))
	rec := putSilence(t, h, "s1", body)
	if rec.Code != http.StatusCreated {
		t.Fatalf("create = %d %q", rec.Code, rec.Body.String())
	}
	got := decodeBody(t, rec)
	if got["id"] != "s1" || got["state"] != "upcoming" || got["comment"] != "maint" ||
		got["starts_at"] != rfc3339(now.Add(time.Hour)) {
		t.Fatalf("create payload = %v", got)
	}
	rids := got["rule_ids"].([]any)
	if len(rids) != 1 || rids[0] != "future_rule" {
		t.Fatalf("rule_ids = %v", rids)
	}

	// Active silence.
	bodyActive := fmt.Sprintf(`{"rule_ids":["r_a","r_b"],"starts_at":%q,"ends_at":%q,"comment":"now"}`,
		rfc3339(now.Add(-time.Minute)), rfc3339(now.Add(time.Minute)))
	if rec = putSilence(t, h, "s_active", bodyActive); rec.Code != http.StatusCreated {
		t.Fatalf("active create = %d", rec.Code)
	}
	if st := decodeBody(t, rec)["state"]; st != "active" {
		t.Fatalf("state = %v", st)
	}

	// Expired silence retained.
	bodyExp := fmt.Sprintf(`{"rule_ids":["r_old"],"starts_at":%q,"ends_at":%q,"comment":"old"}`,
		rfc3339(now.Add(-2*time.Hour)), rfc3339(now.Add(-time.Hour)))
	putSilence(t, h, "s_exp", bodyExp)

	// GET single expired.
	rec = silenceReq(t, h, http.MethodGet, "s_exp", "", "")
	if rec.Code != http.StatusOK || decodeBody(t, rec)["state"] != "expired" {
		t.Fatalf("get expired = %d %v", rec.Code, rec.Body.String())
	}

	// List sorted by id: s1, s_active, s_exp.
	rec = silenceReq(t, h, http.MethodGet, "", "", "")
	list := decodeBody(t, rec)["silences"].([]any)
	if len(list) != 3 {
		t.Fatalf("list len = %d", len(list))
	}
	for i, want := range []string{"s1", "s_active", "s_exp"} {
		if list[i].(map[string]any)["id"] != want {
			t.Fatalf("order[%d] = %v", i, list)
		}
	}

	// Replace -> 200, state recomputed.
	body2 := fmt.Sprintf(`{"rule_ids":["x"],"starts_at":%q,"ends_at":%q,"comment":"v2"}`,
		rfc3339(now.Add(-time.Minute)), rfc3339(now.Add(time.Minute)))
	rec = putSilence(t, h, "s1", body2)
	if rec.Code != http.StatusOK || decodeBody(t, rec)["state"] != "active" {
		t.Fatalf("replace = %d %v", rec.Code, rec.Body.String())
	}

	// DELETE + 404.
	rec = silenceReq(t, h, http.MethodDelete, "s_exp", "", "")
	if rec.Code != http.StatusNoContent || rec.Body.Len() != 0 {
		t.Fatalf("delete = %d", rec.Code)
	}
	expectErrorCode(t, silenceReq(t, h, http.MethodGet, "s_exp", "", ""), http.StatusNotFound, "silence_not_found")
	expectErrorCode(t, silenceReq(t, h, http.MethodDelete, "s_exp", "", ""), http.StatusNotFound, "silence_not_found")
}

func TestSilenceAlertsEnrichment(t *testing.T) {
	h := Handler()
	postMetrics(t, h, `{"samples":[{"name":"hits","type":"gauge","labels":{},"value":9}]}`, "")
	putRule(t, h, "r_fire", `{"kind":"threshold","operator":"gt","threshold":1,"metric":"hits","labels":{}}`)
	putRule(t, h, "r_idle", `{"kind":"threshold","operator":"gt","threshold":100,"metric":"hits","labels":{}}`)
	putRule(t, h, "r_nodata", `{"kind":"threshold","operator":"gt","threshold":1,"metric":"ghost","labels":{}}`)

	now := time.Now()
	// Active silence covering r_fire (and nonexistent rules are fine).
	putSilence(t, h, "zeta", fmt.Sprintf(`{"rule_ids":["r_fire"],"starts_at":%q,"ends_at":%q,"comment":"c"}`,
		rfc3339(now.Add(-time.Minute)), rfc3339(now.Add(time.Minute))))
	// Second active silence on same rule -> ids sorted lexicographically.
	putSilence(t, h, "alpha", fmt.Sprintf(`{"rule_ids":["r_fire"],"starts_at":%q,"ends_at":%q,"comment":"c"}`,
		rfc3339(now.Add(-time.Minute)), rfc3339(now.Add(time.Minute))))
	// Upcoming and expired silences on r_fire: no effect.
	putSilence(t, h, "future", fmt.Sprintf(`{"rule_ids":["r_fire"],"starts_at":%q,"ends_at":%q,"comment":"c"}`,
		rfc3339(now.Add(time.Hour)), rfc3339(now.Add(2*time.Hour))))
	putSilence(t, h, "past", fmt.Sprintf(`{"rule_ids":["r_fire"],"starts_at":%q,"ends_at":%q,"comment":"c"}`,
		rfc3339(now.Add(-2*time.Hour)), rfc3339(now.Add(-time.Hour))))
	// Active silence on non-firing rules.
	putSilence(t, h, "sidle", fmt.Sprintf(`{"rule_ids":["r_idle","r_nodata"],"starts_at":%q,"ends_at":%q,"comment":"c"}`,
		rfc3339(now.Add(-time.Minute)), rfc3339(now.Add(time.Minute))))

	alerts := alertsByID(t, getAlerts(t, h))
	fire := alerts["r_fire"].(map[string]any)
	if fire["state"] != "firing" || fire["silenced"] != true {
		t.Fatalf("r_fire = %v", fire)
	}
	ids := fire["silence_ids"].([]any)
	if fmt.Sprint(ids) != "[alpha zeta]" {
		t.Fatalf("silence_ids = %v", ids)
	}
	for _, id := range []string{"r_idle", "r_nodata"} {
		a := alerts[id].(map[string]any)
		if a["silenced"] != false {
			t.Fatalf("%s silenced = %v", id, a["silenced"])
		}
		if s := a["silence_ids"].([]any); len(s) != 0 {
			t.Fatalf("%s silence_ids = %v", id, s)
		}
	}
}

func TestSilenceWindowBoundaries(t *testing.T) {
	// starts_at == now => active; ends_at == now => expired. Check store-level.
	now := time.Now().Truncate(time.Second)
	s := &silence{startsAt: now, endsAt: now.Add(time.Minute)}
	if !s.activeAt(now) || s.stateAt(now) != "active" {
		t.Fatal("boundary start should be active")
	}
	s2 := &silence{startsAt: now.Add(-time.Minute), endsAt: now}
	if s2.activeAt(now) || s2.stateAt(now) != "expired" {
		t.Fatal("boundary end should be expired")
	}
}

func TestInvalidSilenceBodies(t *testing.T) {
	h := Handler()
	now := time.Now()
	start := rfc3339(now.Add(-time.Minute))
	end := rfc3339(now.Add(time.Minute))
	good := fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":%q,"ends_at":%q,"comment":"c"}`, start, end)

	cases := map[string]string{
		"not json":          `{`,
		"not object":        `[1]`,
		"null":              `null`,
		"unknown field":     fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":%q,"ends_at":%q,"comment":"c","x":1}`, start, end),
		"missing rule_ids":  fmt.Sprintf(`{"starts_at":%q,"ends_at":%q,"comment":"c"}`, start, end),
		"missing starts_at": fmt.Sprintf(`{"rule_ids":["r1"],"ends_at":%q,"comment":"c"}`, end),
		"missing ends_at":   fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":%q,"comment":"c"}`, start),
		"missing comment":   fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":%q,"ends_at":%q}`, start, end),
		"empty rule_ids":    fmt.Sprintf(`{"rule_ids":[],"starts_at":%q,"ends_at":%q,"comment":"c"}`, start, end),
		"dup rule_ids":      fmt.Sprintf(`{"rule_ids":["r1","r1"],"starts_at":%q,"ends_at":%q,"comment":"c"}`, start, end),
		"bad rule id":       fmt.Sprintf(`{"rule_ids":["1r"],"starts_at":%q,"ends_at":%q,"comment":"c"}`, start, end),
		"rule id number":    fmt.Sprintf(`{"rule_ids":[1],"starts_at":%q,"ends_at":%q,"comment":"c"}`, start, end),
		"bad starts_at":     fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":"tomorrow","ends_at":%q,"comment":"c"}`, end),
		"naive timestamp":   fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":"2026-01-01T00:00:00","ends_at":%q,"comment":"c"}`, end),
		"start == end":      fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":%q,"ends_at":%q,"comment":"c"}`, start, start),
		"start > end":       fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":%q,"ends_at":%q,"comment":"c"}`, end, start),
		"comment number":    fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":%q,"ends_at":%q,"comment":1}`, start, end),
		"comment null":      fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":%q,"ends_at":%q,"comment":null}`, start, end),
		"starts_at number":  fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":1,"ends_at":%q,"comment":"c"}`, end),
		"two values":        good + " {}",
		"id in body":        fmt.Sprintf(`{"id":"x","rule_ids":["r1"],"starts_at":%q,"ends_at":%q,"comment":"c"}`, start, end),
	}
	for name, body := range cases {
		t.Run(name, func(t *testing.T) {
			expectErrorCode(t, putSilence(t, h, "s1", body), http.StatusBadRequest, "invalid_silence")
		})
	}

	// Empty comment is allowed (must be a string, not non-empty).
	emptyComment := fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":%q,"ends_at":%q,"comment":""}`, start, end)
	if rec := putSilence(t, h, "s_empty", emptyComment); rec.Code != http.StatusCreated {
		t.Fatalf("empty comment = %d %q", rec.Code, rec.Body.String())
	}

	// Failed replace keeps old value.
	if rec := putSilence(t, h, "s_keep", good); rec.Code != http.StatusCreated {
		t.Fatalf("setup = %d", rec.Code)
	}
	expectErrorCode(t, putSilence(t, h, "s_keep", `{"bogus":1}`), http.StatusBadRequest, "invalid_silence")
	rec := silenceReq(t, h, http.MethodGet, "s_keep", "", "")
	if c := decodeBody(t, rec)["comment"]; c != "c" {
		t.Fatalf("old silence changed: %v", rec.Body.String())
	}
}

func TestSilenceMediaTypesMethodsAndIDs(t *testing.T) {
	h := Handler()
	now := time.Now()
	good := fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":%q,"ends_at":%q,"comment":"c"}`,
		rfc3339(now.Add(-time.Minute)), rfc3339(now.Add(time.Minute)))

	rec := silenceReq(t, h, http.MethodPut, "s1", good, "text/plain")
	expectErrorCode(t, rec, http.StatusUnsupportedMediaType, "unsupported_media_type")
	rec = silenceReq(t, h, http.MethodPut, "s1", good, "")
	expectErrorCode(t, rec, http.StatusUnsupportedMediaType, "unsupported_media_type")

	for _, method := range []string{http.MethodPost, http.MethodPatch} {
		rec = silenceReq(t, h, method, "s1", "", "")
		if rec.Code != http.StatusMethodNotAllowed || rec.Header().Get("Allow") != "GET, PUT, DELETE" {
			t.Fatalf("%s item = %d allow=%q", method, rec.Code, rec.Header().Get("Allow"))
		}
	}
	for _, method := range []string{http.MethodPost, http.MethodPut, http.MethodDelete} {
		rec = silenceReq(t, h, method, "", "", "")
		if rec.Code != http.StatusMethodNotAllowed || rec.Header().Get("Allow") != "GET" {
			t.Fatalf("%s collection = %d allow=%q", method, rec.Code, rec.Header().Get("Allow"))
		}
	}

	// Bad ids: GET/DELETE -> 404, PUT -> 400.
	for _, id := range []string{"1bad", "a-b"} {
		expectErrorCode(t, silenceReq(t, h, http.MethodGet, id, "", ""), http.StatusNotFound, "silence_not_found")
		expectErrorCode(t, h_resp(h, id, good), 0, "")
	}
}

func h_resp(h http.Handler, id, body string) *httptest.ResponseRecorder {
	return nil // placeholder replaced below
}

func TestSilenceBadIDs(t *testing.T) {
	h := Handler()
	now := time.Now()
	good := fmt.Sprintf(`{"rule_ids":["r1"],"starts_at":%q,"ends_at":%q,"comment":"c"}`,
		rfc3339(now.Add(-time.Minute)), rfc3339(now.Add(time.Minute)))
	for _, id := range []string{"1bad", "a-b"} {
		expectErrorCode(t, silenceReq(t, h, http.MethodGet, id, "", ""), http.StatusNotFound, "silence_not_found")
		expectErrorCode(t, silenceReq(t, h, http.MethodDelete, id, "", ""), http.StatusNotFound, "silence_not_found")
		expectErrorCode(t, silenceReq(t, h, http.MethodPut, id, good, "application/json"),
			http.StatusBadRequest, "invalid_silence")
	}
	// Nested paths -> 404 silence_not_found.
	for _, target := range []string{silencesPrefix + "s1/extra"} {
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, target, nil))
		if rec.Code != http.StatusNotFound {
			t.Fatalf("nested = %d", rec.Code)
		}
	}
	// Valid ids.
	for _, id := range []string{"a", "_x", "A9_b"} {
		if rec := putSilence(t, h, id, good); rec.Code != http.StatusCreated {
			t.Fatalf("valid id %q = %d %q", id, rec.Code, rec.Body.String())
		}
	}

	// Empty collection shape.
	h2 := Handler()
	rec := httptest.NewRecorder()
	h2.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, silencesPath, nil))
	if strings.TrimSpace(rec.Body.String()) != `{"silences":[]}` {
		t.Fatalf("empty = %q", rec.Body.String())
	}
}

func TestSilenceResponseShape(t *testing.T) {
	h := Handler()
	now := time.Now()
	body := fmt.Sprintf(`{"rule_ids":["r1","r2"],"starts_at":%q,"ends_at":%q,"comment":"c"}`,
		rfc3339(now.Add(time.Hour)), rfc3339(now.Add(2*time.Hour)))
	putSilence(t, h, "s1", body)
	var raw map[string]json.RawMessage
	rec := silenceReq(t, h, http.MethodGet, "s1", "", "")
	_ = json.Unmarshal(rec.Body.Bytes(), &raw)
	for _, k := range []string{"id", "rule_ids", "starts_at", "ends_at", "comment", "state"} {
		if _, ok := raw[k]; !ok {
			t.Fatalf("missing key %q in %s", k, rec.Body.String())
		}
	}
	if len(raw) != 6 {
		t.Fatalf("unexpected keys: %v", raw)
	}
}

